/**
 * Returns a greeting based on a name and time of day.
 *
 * @param {string} name - The name of the person to greet.
 * @param {string|number} timeOfDay - Either a period ("morning", "afternoon",
 *   "evening", "night") or an hour of the day (0–23).
 * @returns {string} A personalized greeting.
 */
function getGreeting(name, timeOfDay) {
  const greetings = {
    morning: "Good morning",
    afternoon: "Good afternoon",
    evening: "Good evening",
    night: "Good night",
  };

  // Clean up the name, falling back to a default
  const displayName =
    typeof name === "string" && name.trim() ? name.trim() : "there";

  let period;

  if (typeof timeOfDay === "number") {
    // Convert an hour (0–23) into a period of the day
    if (!Number.isInteger(timeOfDay) || timeOfDay < 0 || timeOfDay > 23) {
      throw new RangeError("Hour must be an integer between 0 and 23.");
    }
    if (timeOfDay >= 5 && timeOfDay < 12) period = "morning";
    else if (timeOfDay >= 12 && timeOfDay < 17) period = "afternoon";
    else if (timeOfDay >= 17 && timeOfDay < 21) period = "evening";
    else period = "night";
  } else if (typeof timeOfDay === "string") {
    period = timeOfDay.trim().toLowerCase();
  }

  const greeting = greetings[period] || "Hello";
  return `${greeting}, ${displayName}!`;
}

// Example usage:
console.log(getGreeting("Alice", "morning"));   // "Good morning, Alice!"
console.log(getGreeting("Bob", "Evening"));     // "Good evening, Bob!"
console.log(getGreeting("Charlie", 14));        // "Good afternoon, Charlie!"
console.log(getGreeting("Dana", 22));           // "Good night, Dana!"
console.log(getGreeting("Eve", "brunch"));      // "Hello, Eve!"
console.log(getGreeting("", "morning"));        // "Good morning, there!"

// Greeting based on the current time:
