```javascript
/**
 * Constructs a formatted log line.
 *
 * @param {string} level - Log level (e.g., "info", "warn", "error", "debug").
 * @param {string|*} message - The log message. Non-string values are serialized.
 * @param {Date|number|string} [timestamp=new Date()] - A Date, epoch ms, or parseable date string.
 * @returns {string} A formatted log line, e.g. "2024-05-01T12:34:56.789Z [INFO] Server started"
 */
function formatLogLine(level, message, timestamp = new Date()) {
  const VALID_LEVELS = ['TRACE', 'DEBUG', 'INFO', 'WARN', 'ERROR', 'FATAL'];

  // Normalize level
  const normalizedLevel = String(level ?? 'INFO').trim().toUpperCase();
  if (!VALID_LEVELS.includes(normalizedLevel)) {
    throw new Error(
      `Invalid log level "${level}". Expected one of: ${VALID_LEVELS.join(', ')}`
    );
  }

  // Normalize timestamp
  const date = timestamp instanceof Date ? timestamp : new Date(timestamp);
  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid timestamp: ${timestamp}`);
  }

  // Normalize message
  let text;
  if (message instanceof Error) {
    text = message.stack || `${message.name}: ${message.message}`;
  } else if (typeof message === 'string') {
    text = message;
  } else {
    try {
      text = JSON.stringify(message);
    } catch {
      text = String(message); // e.g. circular structures
    }
  }

  // Escape newlines so each entry stays on a single line
  // (prevents log injection / forged log entries)
  text = String(text).replace(/\r/g, '\\r').replace(/\n/g, '\\n');

  // Pad level so messages align in columns
  const paddedLevel = `[${normalizedLevel}]`.padEnd(7);

  return `${date.toISOString()} ${paddedLevel} ${text}`;
}

module.exports = { formatLogLine };
```

### Example usage

