  text = text.replace(/\r/g, "\\r").replace(/\n/g, "\\n");

  // Pad level so messages align in columns (longest level is 5 chars)
  const levelTag = normalizedLevel.toUpperCase().padEnd(5);

  return `[${date.toISOString()}] [${levelTag}] ${text}`;
