/**
 * Constructs a log line from a level, message, and timestamp.
 *
 * @param {string} level - Log level (e.g., "info", "warn", "error").
 * @param {string} message - The log message.
 * @param {Date|number|string} [timestamp=new Date()] - Date object, epoch ms, or date string.
 * @returns {string} Formatted log line.
 */
function buildLogLine(level, message, timestamp = new Date()) {
  const date = timestamp instanceof Date ? timestamp : new Date(timestamp);

  if (isNaN(date.getTime())) {
    throw new TypeError("Invalid timestamp");
  }

  const lvl = String(level).toUpperCase();
  // Keep each entry on a single line by escaping newlines
  const msg = String(message).replace(/\r?\n/g, "\\n");

  return `[${date.toISOString()}] [${lvl}] ${msg}`;
}
