console.log(greet("Charlie", "evening")); // "Good evening, Charlie!"
```

### Alternative: Using an hour (0–23)
If you want to pass the time as a 24-hour number instead of a word, you can do this:

```javascript
function greetByHour(name, hour) {
  let timeOfDay;

  if (hour < 12) {
    timeOfDay = "morning";
  } else if (hour < 18) {
    timeOfDay = "afternoon";
  } else {
    timeOfDay = "evening";
  }

  return `Good ${timeOfDay}, ${name}!`;
}

// Examples:
console.log(greetByHour("Alice", 9));  // "Good morning, Alice!"
console.log(greetByHour("Bob", 14));   // "Good afternoon, Bob!"
console.log(greetByHour("Charlie", 20)); // "Good evening, Charlie!"
```

