 * Builds the value for an HTTP Authorization header using Bearer auth.
 *
 * @param {string} token - The bearer token.
 * @returns {string} For example: "Bearer abc123".
 */
function buildBearerAuthorization(token) {
  if (typeof token !== "string" || token.trim() === "") {
    throw new TypeError("Bearer token must be a non-empty string.");
  }

  const normalizedToken = token.trim();

  if (/[\r\n]/.test(normalizedToken)) {
    throw new TypeError("Bearer token must not contain line breaks.");
  }

  return `Bearer ${normalizedToken}`;
}

