  const ts = isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString();

  // Uppercase the level for consistency
  const lvl = String(level).toUpperCase();

  // Coerce the message to a string
  const msg = typeof message === 'string' ? message : String(message);

  return `[${ts}] [${lvl}] ${msg}`;
}
```

### Example usage

```js
