    throw new TypeError('timestamp must be a valid Date, ISO string, or epoch number');
  }

  const iso = date.toISOString();
  const upperLevel = level.toUpperCase().padEnd(5, ' ');

  return `[${iso}] ${upperLevel} ${message}`;
}
```

