 * Builds a single log line from a level, message, and timestamp.
 *
 * @param {string} level            - e.g. "INFO", "WARN", "ERROR"
 * @param {string} message          - The message body
 * @param {Date|string|number} [timestamp] - Defaults to now
 * @param {object} [options]
 * @param {string} [options.levelSeparator=": "] - Text between level and message
 * @param {boolean} [options.uppercaseLevel=true]
 * @param {string} [options.prefix=""] - Prepended to the whole line
 * @returns {string}
 */
function formatLogLine(level, message, timestamp = new Date(), options = {}) {
  const {
    levelSeparator = ": ",
    uppercaseLevel = true,
    prefix = "",
  } = options;

  if (typeof level !== "string" || level.trim() === "") {
    throw new TypeError("level must be a non-empty string");
  }
  if (typeof message !== "string") {
    throw new TypeError("message must be a string");
  }

