 * @param {Date|string|number} timestamp - When the event occurred
 * @param {object} [options]
 * @param {string} [options.format="iso"] - "iso" | "locale" | "epoch"
 * @param {string} [options.separator=" "] - Separator between fields
 * @returns {string}
 */
