  const { format = "iso", separator = " " } = options;

  if (typeof level !== "string" || level.trim() === "") {
    throw new TypeError("level must be a non-empty string");
  }
  if (typeof message !== "string") {
    throw new TypeError("message must be a string");
  }

  const date = timestamp instanceof Date ? timestamp : new Date(timestamp);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError("timestamp is not a valid date");
  }

  let formattedTime;
  switch (format) {
    case "epoch":
      formattedTime = String(date.getTime());
      break;
    case "locale":
      formattedTime = date.toLocaleString();
      break;
    case "iso":
    default:
      formattedTime = date.toISOString();
      break;
  }

  return `[${formattedTime}] ${level.toUpperCase()}${separator}${message}`;
}
