## `formatLogLine`

```js
/**
 * Builds a single log line from a level, a message, and a timestamp.
 *
 * @param {string} level  - Log level, e.g. "info", "WARN", "error".
 * @param {*} message      - Message to log. Strings pass through; other values
 *                          are serialized (Errors use their stack).
 * @param {Date|number|string} [timestamp] - Date, epoch-ms number, or
 *                          parseable date string. Defaults to now.
 * @param {object} [options]
 * @param {"iso"|"epoch"|"locale"} [options.format="iso"] - Timestamp format.
 * @param {string} [options.separator=": "] - Text between level and message.
 * @param {boolean} [options.escapeNewlines=false] - Keep the line single-line.
 * @returns {string}
 */
function formatLogLine(level, message, timestamp = new Date(), options = {}) {
  const { format = "iso", separator = ": ", escapeNewlines = false } = options;

  if (level === null || level === undefined || String(level).trim() === "") {
    throw new TypeError("formatLogLine: level is required");
  }

  const date = timestamp === null || timestamp === undefined
    ? new Date()
    : timestamp instanceof Date
      ? timestamp
      : new Date(timestamp);

  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatLogLine: invalid timestamp ${String(timestamp)}`);
  }

  const normalizedLevel = String(level).trim().toUpperCase();
  let text = typeof message === "string" ? message : safeStringify(message);

  if (escapeNewlines) {
    text = text.replace(/\r\n|\r|\n/g, "\\n");
  }

  return `[${formatTimestamp(date, format)}] ${normalizedLevel}${separator}${text}`;
}

function formatTimestamp(date, format) {
  switch (format) {
    case "epoch":
      return String(date.getTime());
    case "locale":
      return date.toLocaleString();
    case "iso":
    default:
      return date.toISOString();
  }
}

function safeStringify(value) {
  if (value instanceof Error) {
    return value.stack || `${value.name}: ${value.message}`;
  }
  try {
    const seen = new WeakSet();
    const json = JSON.stringify(value, (_key, val) => {
      if (typeof val === "bigint") return val.toString();
      if (typeof val === "object" && val !== null) {
        if (seen.has(val)) return "[Circular]";
        seen.add(val);
      }
      return val;
    });
    return json === undefined ? String(value) : json;
  } catch {
    return String(value);
  }
}
```

### Usage

