  if (validateLevel && !LOG_LEVELS.includes(normalizedLevel)) {
    throw new RangeError(`Unknown log level: ${normalizedLevel}`);
  }

  // --- build the line --------------------------------------------------
  const ts = formatTimestamp(date);
  const head = includeLevel
    ? `[${ts}] ${normalizedLevel}${separator}`
    : `[${ts}]${separator}`;

  return `${head}${message}`;
}
```

