```js
/**
 * Build a single log line.
 *
 * @param {string} level  Log level, e.g. "info" or "ERROR".
 * @param {*} message      Message content (strings, objects, Errors, ...).
 * @param {Date|number|string} [timestamp] Defaults to the current time.
 * @param {object} [options]
 * @param {number} [options.levelPadding=0]  Pad the level to this width.
 * @param {boolean} [options.singleLine=true] Escape newlines in the message.
 * @returns {string}
 */
function formatLogLine(level, message, timestamp = new Date(), options = {}) {
  const { levelPadding = 0, singleLine = true } = options;

  // --- level ---
  const normalizedLevel = String(level ?? 'INFO')
    .toUpperCase()
    .padEnd(levelPadding);

  // --- timestamp ---
  const date =
    timestamp instanceof Date
      ? timestamp
      : new Date(typeof timestamp === 'string' ? Date.parse(timestamp) : timestamp);

  // If the timestamp can't be parsed, fall back to the raw value.
  const timePart = Number.isNaN(date.getTime())
    ? String(timestamp)
    : date.toISOString();

  // --- message ---
  let text;
  if (message instanceof Error) {
    text = message.stack ?? message.message;
  } else if (typeof message === 'string') {
    text = message;
  } else {
    text = safeStringify(message);
  }

  if (singleLine) {
    text = text.replace(/\r\n|\r|\n/g, '\\n');
  }

  return `[${timePart}] ${normalizedLevel}: ${text}`;
}

/** JSON.stringify that survives circular references and BigInt. */
function safeStringify(value) {
  const seen = new WeakSet();
  try {
    return JSON.stringify(value, (key, val) => {
      if (typeof val === 'bigint') return val.toString();
      if (typeof val === 'object' && val !== null) {
        if (seen.has(val)) return '[Circular]';
        seen.add(val);
      }
      return val;
    }) ?? String(value);
  } catch {
    return String(value);
  }
}
