/** Normalize any supported timestamp input to an ISO-8601 string. */
function normalizeTimestamp(timestamp) {
  if (timestamp instanceof Date) {
    return Number.isNaN(timestamp.getTime())
      ? "Invalid Date"
      : timestamp.toISOString();
  }
  if (typeof timestamp === "number") {
    return new Date(timestamp).toISOString(); // epoch milliseconds
  }
  if (typeof timestamp === "string") {
    const parsed = Date.parse(timestamp);
    return Number.isNaN(parsed) ? timestamp : new Date(parsed).toISOString();
  }
  return new Date().toISOString();
}

/** Turn a message into a single-line string, escaping embedded newlines. */
function stringifyMessage(message) {
  let text;
  if (typeof message === "string") {
    text = message;
  } else if (message instanceof Error) {
    text = message.stack ?? `${message.name}: ${message.message}`;
  } else {
    try {
      text = JSON.stringify(message);
    } catch {
      text = String(message); // circular structures, BigInt, etc.
    }
    if (text === undefined) text = String(message);
  }
  // Keep the log on one line.
  return text.replace(/\r\n|\r|\n/g, "\\n");
}
