```js
/**
 * Build an HTTP `Authorization` header value for Bearer token auth.
 *
 * @param {string} token  Raw access token (WITHOUT the "Bearer " prefix).
 * @param {object} [options]
 * @param {boolean} [options.strict = true]
 *   true  -> token must match the RFC 6750 `b64token` grammar
 *   false -> only characters unsafe in a header value are rejected
 * @returns {string} e.g. "Bearer eyJhbGciOiJIUzI1NiJ9..."
 * @throws {TypeError}  token is not a string
 * @throws {RangeError} token is empty or contains invalid characters
 */
export function buildBearerAuthorization(token, { strict = true } = {}) {
  if (typeof token !== 'string') {
    throw new TypeError('token must be a string');
  }

  const value = token.trim();
  if (value.length === 0) {
    throw new RangeError('token must not be empty');
  }

  // RFC 6750 b64token: ALPHA / DIGIT / "-" / "." / "_" / "~" / "+" / "/" then *"="
  const B64TOKEN = /^[A-Za-z0-9\-._~+/]+=*$/;

  if (strict) {
    if (!B64TOKEN.test(value)) {
      throw new RangeError('token contains characters not allowed in a Bearer token');
    }
